package main

// The /mcp composition tools against pflow-native. The pflow_bundle_* cases of
// parity/native/mcp_cases.json are answered by pflow-native's composition rules
// (generated by parity/native/gen/src/bundle.rs, `make native-goldens`) into
// parity/native/mcp_goldens.json; this replays every call through the tool's
// own handler and compares, the way mcp_workbench_parity_test.go does for the
// workbench tools. The answers are compared exactly: strings, booleans, null,
// structure and every integer, each of the same JSON type on both sides. A
// bundle has no floating-point answer.
//
// Where the bundle comes from:
//
//   - a `composition` case is the catalog composition native opens
//     (bundle.open); the golden holds the bundle native built and serialised
//     (pflow-compose's wire format, the one go-pflow reads). The tool is run on
//     that bundle, and again on the one pflow_bundle_example builds with
//     go-pflow's constructors from the same instances and links: both must
//     give native's answer;
//   - a `bundle_file` case is a PetriNetBundle document (the cafe showcase, the
//     fixtures under native/fixtures). The registry cannot open one at the
//     pinned pflow-native, so the golden is the composition module's functions
//     those commands call, run on the document (see bundle.rs).
//
// pflow_bundle_example is checked field by field: the catalog, the scenarios,
// the default links and the refusals are native's, and the subnets and links of
// the bundle it builds are native's places, transitions, arcs, ports and
// constraints (TestMCPBundleCatalogMatchesNative).

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"sort"
	"strings"
	"testing"

	"github.com/pflow-xyz/go-pflow/metamodel"
)

type bundleGoldenCase struct {
	Name        string         `json:"name"`
	Tool        string         `json:"tool"`
	Args        map[string]any `json:"args"`
	Composition string         `json:"composition"` // a name in the goldens' compositions
	BundleFile  string         `json:"bundle_file"`
	Expect      any            `json:"expect"`
	Error       *string        `json:"error"`
	Subnets     []any          `json:"subnets"`
	Links       []any          `json:"links"`
}

// bundleGoldens are the pflow_bundle_* cases and the compositions they name:
// each the arguments bundle.open took and the bundle native built.
type bundleGoldens struct {
	Compositions map[string]struct {
		Args   map[string]any `json:"args"`
		Bundle map[string]any `json:"bundle"`
	} `json:"compositions"`
	Cases []bundleGoldenCase
}

var bundleHandlers = map[string]func(*Server, *http.Request, map[string]any) (any, error){
	"pflow_bundle_example": mcpBundleExample, "pflow_bundle_validate": mcpBundleValidate,
	"pflow_bundle_add_link": mcpBundleAddLink, "pflow_bundle_candidates": mcpBundleCandidates,
	"pflow_bundle_flatten": mcpBundleFlatten, "pflow_bundle_run": mcpBundleRun,
	"pflow_bundle_incidence": mcpBundleIncidence,
}

func loadBundleGoldens(t *testing.T) bundleGoldens {
	t.Helper()
	var golden struct {
		PflowNative  string `json:"pflow_native"`
		Compositions map[string]struct {
			Args   map[string]any `json:"args"`
			Bundle map[string]any `json:"bundle"`
		} `json:"compositions"`
		Cases []bundleGoldenCase `json:"cases"`
	}
	loadJSON(t, "../../parity/native/mcp_goldens.json", &golden)
	var lock struct {
		Commit string `json:"commit"`
	}
	loadJSON(t, "../../pflow-native-wasm.lock", &lock)
	if golden.PflowNative != lock.Commit {
		t.Fatalf("mcp_goldens.json was generated against pflow-native %s, but the vendored wasm is %s; re-run `make native-goldens`", golden.PflowNative, lock.Commit)
	}
	out := bundleGoldens{Compositions: golden.Compositions}
	for _, c := range golden.Cases {
		if strings.HasPrefix(c.Tool, "pflow_bundle_") {
			out.Cases = append(out.Cases, c)
		}
	}
	return out
}

// callBundleTool runs a tool's handler the way a call does, on a JSON copy of
// the arguments (a handler never sees Go values a client could not send).
func callBundleTool(t *testing.T, tool string, args map[string]any) (any, error) {
	t.Helper()
	run, ok := bundleHandlers[tool]
	if !ok {
		t.Fatalf("no handler for %s", tool)
	}
	text, err := json.Marshal(args)
	if err != nil {
		t.Fatal(err)
	}
	var sent map[string]any
	if err := json.Unmarshal(text, &sent); err != nil {
		t.Fatal(err)
	}
	return run(&Server{}, httptest.NewRequest("POST", "/mcp", nil), sent)
}

// asJSON is what a client receives for a tool's answer.
func asJSON(t *testing.T, v any) any {
	t.Helper()
	text, err := json.Marshal(v)
	if err != nil {
		t.Fatalf("the answer is not JSON: %v", err)
	}
	var out any
	if err := json.Unmarshal(text, &out); err != nil {
		t.Fatal(err)
	}
	return out
}

func compareToGolden(t *testing.T, c bundleGoldenCase, out any, err error, what string) {
	t.Helper()
	if c.Error != nil {
		if err == nil {
			t.Fatalf("%s: native refused (%s); the tool answered", what, *c.Error)
		}
		// the tool names itself in front of a refusal and may add a hint behind
		// it; the words between are native's
		if mbNativeText(err) != *c.Error {
			t.Fatalf("%s: error differs:\n tool:   %s\n native: %s", what, err.Error(), *c.Error)
		}
		return
	}
	if err != nil {
		t.Fatalf("%s: tool error: %v", what, err)
	}
	got := asJSON(t, out)
	// pflow_bundle_flatten and pflow_bundle_incidence add `notes` when an arc has
	// no weight (it counts as 0 in the arcs and the matrix but fires as 1: native
	// does the same and says nothing). It is the one key the tool adds to
	// native's answer, so it is the one key not compared (TestMCPBundleNotesSayWhatNativeDoesNot).
	if m, ok := got.(map[string]any); ok && (c.Tool == "pflow_bundle_flatten" || c.Tool == "pflow_bundle_incidence") {
		delete(m, "notes")
	}
	if d := jsonDiff(c.Expect, got, "", constTolerance(0), nil); len(d) > 0 {
		if len(d) > 20 {
			d = append(d[:20], fmt.Sprintf("… %d more", len(d)-20))
		}
		t.Fatalf("%s: differs from native:\n%s", what, strings.Join(d, "\n"))
	}
}

func TestMCPBundleToolsMatchNative(t *testing.T) {
	seen := map[string]bool{}
	goldens := loadBundleGoldens(t)
	for _, c := range goldens.Cases {
		if c.Tool == "pflow_bundle_example" {
			continue // TestMCPBundleCatalogMatchesNative
		}
		t.Run(c.Name, func(t *testing.T) {
			args := map[string]any{}
			for k, v := range c.Args {
				args[k] = v
			}
			switch {
			case c.BundleFile != "":
				var doc map[string]any
				loadJSON(t, "../../parity/"+c.BundleFile, &doc)
				args["bundle"] = doc
				out, err := callBundleTool(t, c.Tool, args)
				compareToGolden(t, c, out, err, "on the document")
			default:
				comp, ok := goldens.Compositions[c.Composition]
				if !ok {
					t.Fatalf("no composition %q in the goldens", c.Composition)
				}
				// native's own subnets, as native serialised them
				args["bundle"] = comp.Bundle
				out, err := callBundleTool(t, c.Tool, args)
				compareToGolden(t, c, out, err, "on native's bundle")
				// and the ones go-pflow's constructors build from the same instances and links
				built, err := callBundleTool(t, "pflow_bundle_example", comp.Args)
				if err != nil {
					t.Fatalf("pflow_bundle_example: %v", err)
				}
				args["bundle"] = asJSON(t, built).(map[string]any)["bundle"]
				out, err = callBundleTool(t, c.Tool, args)
				compareToGolden(t, c, out, err, "on the bundle pflow_bundle_example builds")
			}
		})
		if c.Error == nil {
			seen[c.Tool] = true
		}
	}
	for tool := range bundleHandlers {
		if tool != "pflow_bundle_example" && !seen[tool] {
			t.Errorf("%s has no successful golden case", tool)
		}
	}
}

// subnetViews is a bundle's subnets reduced to what native's views hold: the
// places, transitions, arcs, ports and constraints each subnet is made of.
func subnetViews(t *testing.T, bundle any) []any {
	t.Helper()
	text, err := json.Marshal(bundle)
	if err != nil {
		t.Fatal(err)
	}
	var b metamodel.Bundle
	if err := json.Unmarshal(text, &b); err != nil {
		t.Fatal(err)
	}
	var out []any
	for _, s := range b.Subnets {
		ports := []any{}
		for _, p := range s.Ports {
			target := "place"
			if p.IsTransition() {
				target = "transition"
			}
			ports = append(ports, map[string]any{
				"id": p.ID, "kind": string(p.Kind), "target": target, "place": p.Place, "transition": p.Transition, "schema": p.Schema,
			})
		}
		places := []any{}
		for i := range s.Model.Places {
			places = append(places, mbPlaceView(&s.Model.Places[i]))
		}
		transitions := []any{}
		for _, tr := range s.Model.Transitions {
			transitions = append(transitions, map[string]any{"id": tr.ID, "description": tr.Description})
		}
		out = append(out, map[string]any{
			"id": s.ID, "net_type": string(s.NetType), "model_name": s.Model.Name,
			"ports": ports, "places": places, "transitions": transitions,
			"arcs": mbArcsView(s.Model), "constraints": mbConstraintsView(s.Model),
		})
	}
	return out
}

func TestMCPBundleCatalogMatchesNative(t *testing.T) {
	n := 0
	for _, c := range loadBundleGoldens(t).Cases {
		if c.Tool != "pflow_bundle_example" {
			continue
		}
		n++
		t.Run(c.Name, func(t *testing.T) {
			out, err := callBundleTool(t, c.Tool, c.Args)
			if c.Error != nil {
				compareToGolden(t, c, out, err, "the example")
				return
			}
			if err != nil {
				t.Fatalf("tool error: %v", err)
			}
			got, _ := asJSON(t, out).(map[string]any)
			bundle := got["bundle"]
			delete(got, "bundle")
			compareToGolden(t, c, got, nil, "the catalog and the scenarios")

			// the subnets go-pflow's constructors build are native's
			if d := jsonDiff(anySlice(c.Subnets), asJSON(t, subnetViews(t, bundle)), ".subnets", constTolerance(0), nil); len(d) > 0 {
				t.Fatalf("the subnets differ from native's:\n%s", strings.Join(d, "\n"))
			}
			// and so are the links the bundle carries
			links := bundle.(map[string]any)["links"]
			if links == nil {
				links = []any{}
			}
			if d := jsonDiff(anySlice(c.Links), anySlice(links), ".links", constTolerance(0), nil); len(d) > 0 {
				t.Fatalf("the links differ from native's:\n%s", strings.Join(d, "\n"))
			}
		})
	}
	if n == 0 {
		t.Fatal("no pflow_bundle_example case in the goldens")
	}
}

func anySlice(v any) any {
	if v == nil {
		return []any{}
	}
	return v
}

// The cases the goldens hold, by tool. A case deleted from mcp_cases.json (and
// the goldens regenerated) would otherwise leave nothing to say that a check had
// gone; add the cases you add here.
var wantBundleCases = map[string]int{
	"pflow_bundle_example": 8, "pflow_bundle_validate": 15, "pflow_bundle_add_link": 30, "pflow_bundle_candidates": 39,
	"pflow_bundle_flatten": 15, "pflow_bundle_run": 35, "pflow_bundle_incidence": 12,
}

// A golden whose bundle came out empty (a generator fault) fails loudly, and
// the goldens cover every tool.
func TestMCPBundleGoldensAreWhole(t *testing.T) {
	goldens := loadBundleGoldens(t)
	have := map[string]int{}
	for _, c := range goldens.Cases {
		have[c.Tool]++
	}
	for tool, want := range wantBundleCases {
		if have[tool] != want {
			t.Errorf("%s: %d cases in the goldens; %d are expected (wantBundleCases): a case was removed, or added without being counted", tool, have[tool], want)
		}
	}
	for name, c := range goldens.Compositions {
		if len(c.Bundle) == 0 {
			t.Errorf("composition %s: no bundle in the golden", name)
		}
	}
	tools := map[string]bool{}
	for _, c := range goldens.Cases {
		tools[c.Tool] = true
		if c.BundleFile != "" {
			if _, err := os.Stat("../../parity/" + c.BundleFile); err != nil {
				t.Errorf("%s: %v", c.Name, err)
			}
		} else if c.Tool != "pflow_bundle_example" && goldens.Compositions[c.Composition].Bundle == nil {
			t.Errorf("%s: composition %q has no bundle", c.Name, c.Composition)
		}
	}
	var got, want []string
	for n := range tools {
		got = append(got, n)
	}
	for n := range bundleHandlers {
		want = append(want, n)
	}
	sort.Strings(got)
	sort.Strings(want)
	if strings.Join(got, " ") != strings.Join(want, " ") {
		t.Errorf("the goldens cover %v; the tools are %v", got, want)
	}
}
